/// <summary>
/// The <c>AVAInventMov_TransferTransitFromCls_Extension</c> represents a extension of the class InventMov_TransferTransitFrom
/// </summary>
[
    ExtensionOf(classStr(InventMov_TransferTransitFrom))
]
final class AVAInventMov_TransferTransitFromCls_Extension
{
}

Method.Source:
/// <summary>
/// Extension Methode for inventDimMerged
/// </summary>
/// <param name = "_inventDim">
/// The InventDim record wit merge data
/// </param>
/// <returns>
/// The new merged InventDim record
/// </returns>
public InventDim inventDimMerged(InventDim _inventDim)
{
    InventDim   avaInventDim;

    avaInventDim = next inventDimMerged(_inventDim);
    avaInventDim = this.avaInventDimMerged(avaInventDim);

    return avaInventDim;
}

/// <summary>
/// ava Methode for inventDimMerged
/// </summary>
/// <param name = "_inventDim">
/// The InventDim record wit merge data
/// </param>
/// <returns>
/// The new merged InventDim record
/// </returns>
public InventDim avaInventDimMerged(InventDim _inventDim)
{
    InventDim                       inventDim;
    WHSLicensePlateId               avaLicensePlateToRegister;
    WHSLicensePlateId               avaLicensePlateInTransit;
    AVARegisterASNItemsIDisposable  avaRegisterASNItemsIDisposable;

    inventDim                       = _inventDim.data();
    avaRegisterASNItemsIDisposable  = AVARegisterASNItemsIDisposable::current();

    if (avaRegisterASNItemsIDisposable
     && avaRegisterASNItemsIDisposable.aktiveProcess == NoYes::Yes)
    {
        avaLicensePlateToRegister   = avaRegisterASNItemsIDisposable.lastLicensePlateToRegister;
        avaLicensePlateInTransit    = avaRegisterASNItemsIDisposable.loopUpLicensePlateToRegister(avaLicensePlateToRegister, false);

        if (avaLicensePlateToRegister
         && avaLicensePlateInTransit
         && inventDim.LicensePlateId == avaLicensePlateToRegister
         && inventDim.LicensePlateId != avaLicensePlateInTransit)
        {
            inventDim.LicensePlateId = avaLicensePlateInTransit;
        }
    }

    return InventDim::findOrCreate(inventDim);
}
